/**
 * Pushes `DEEP_CONTESTS` to Seer's leaderboard registry.
 *
 * The leaderboard here is Seer's board (`netlify/functions/utils/seerLeaderboard.ts`), and Seer only
 * materializes a board for a contest listed in `SEER_APPS.deepfund.markets`
 * (`web/src/lib/apps.ts` in the Seer repo). That list is generated from this repo's contest registry
 * into `web/src/lib/deepfundMarkets.generated.ts`, so a new contest is one entry in `contests.ts`
 * plus one run of this script.
 *
 *   npm run sync:seer                 open a PR on seer-pm/demo with the regenerated file
 *   npm run sync:seer -- --dry-run    print the diff against Seer's origin/main, change nothing
 *   npm run sync:seer -- --write      write the file into the Seer checkout, no git
 *   npm run sync:seer -- --check      report which contests Seer already has a board for
 *
 * The Seer checkout defaults to `D:\Code\demo`; override with `SEER_REPO`. The PR is built in a
 * throwaway git worktree off `origin/main`, so the checkout's own branch and working tree are
 * never touched.
 *
 * A board appears only after the PR is merged and Seer redeploys, and then fills as the refresh
 * reaches each wallet (a lap is several hours). `--check` says when a contest's
 * `leaderboard: false` can come off.
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DEEP_CONTESTS, type Contest } from "@/utils/contests";
import { fetchSeerBoard } from "../netlify/functions/utils/seerLeaderboard";

const SEER_REPO = process.env.SEER_REPO || "D:\\Code\\demo";
const SEER_GITHUB_REPO = "seer-pm/demo";
const GENERATED_PATH = "web/src/lib/deepfundMarkets.generated.ts";

const args = new Set(process.argv.slice(2));

function git(cwd: string, ...gitArgs: string[]): string {
  return execFileSync("git", gitArgs, { cwd, encoding: "utf8" }).trim();
}

function lowerHex(id: string): string {
  return id.toLowerCase();
}

/** One `SeerAppMarket` literal. A contest with a parent sends only the parent; Seer expands it. */
function renderMarket(contest: Contest): string {
  const lines = [
    `  {`,
    `    id: ${JSON.stringify(contest.id)},`,
    `    label: ${JSON.stringify(contest.label)},`,
    `    chainId: optimism.id,`,
  ];
  if (contest.marketId) {
    lines.push(`    marketId: "${lowerHex(contest.marketId)}",`);
  } else if (contest.marketIds?.length) {
    const ids = [...new Set(contest.marketIds.map(lowerHex))].sort();
    lines.push(`    marketIds: [`, ...ids.map((id) => `      "${id}",`), `    ],`);
  } else {
    throw new Error(`contest ${contest.id} has neither marketId nor marketIds`);
  }
  lines.push(`  },`);
  return lines.join("\n");
}

function renderFile(): string {
  // `hidden` only takes a tab out of this app's bar; its board stays on Seer.
  const contests = DEEP_CONTESTS as readonly Contest[];
  return [
    `// GENERATED by ai-prediction-markets \`npm run sync:seer\` (scripts/syncSeerApps.ts) — do not edit.`,
    `// The source of truth is DEEP_CONTESTS in that repo's src/utils/contests.ts.`,
    `import { optimism } from "viem/chains";`,
    `import type { SeerAppMarket } from "./apps";`,
    ``,
    `export const DEEPFUND_MARKETS: SeerAppMarket[] = [`,
    ...contests.map(renderMarket),
    `];`,
    ``,
  ].join("\n");
}

function readOriginMain(path: string): string | null {
  try {
    return execFileSync("git", ["show", `origin/main:${path}`], {
      cwd: SEER_REPO,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
  } catch {
    return null;
  }
}

/** Unified diff of two strings via `git diff --no-index`; empty when equal. */
function diffStrings(before: string, after: string): string {
  const dir = mkdtempSync(join(tmpdir(), "sync-seer-"));
  try {
    writeFileSync(join(dir, "origin-main.ts"), before);
    writeFileSync(join(dir, "generated.ts"), after);
    try {
      execFileSync("git", ["-c", "core.autocrlf=false", "diff", "--no-index", "--no-color", "origin-main.ts", "generated.ts"], {
        cwd: dir,
        encoding: "utf8",
      });
      return "";
    } catch (error) {
      // `git diff --no-index` exits 1 when the files differ.
      return String((error as { stdout?: string }).stdout ?? "");
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

async function check() {
  for (const contest of DEEP_CONTESTS as readonly Contest[]) {
    const flagged = contest.leaderboard === false;
    let status: string;
    try {
      const { rows, updatedAt } = await fetchSeerBoard(contest.id, "all");
      status = rows.length
        ? `${rows.length} rows, oldest ${updatedAt ?? "?"}`
        : "registered, board still empty";
      if (rows.length && flagged) status += "  <- ready: remove `leaderboard: false`";
    } catch (error) {
      const message = (error as Error).message;
      // Seer answers an unregistered scope with the full list of valid app ids; that is noise here.
      status = message.startsWith("app must be one of") ? "not registered on Seer" : `error: ${message}`;
      if (!flagged) status += "  <- set `leaderboard: false` or run sync:seer";
    }
    console.log(`${contest.id.padEnd(12)} ${flagged ? "[off]" : "[on] "} ${status}`);
  }
}

function openPr(content: string) {
  const date = new Date().toISOString().slice(0, 10).replace(/-/g, "");
  const branch = `deepfund/sync-contests-${date}`;
  const worktree = mkdtempSync(join(tmpdir(), "seer-sync-"));
  rmSync(worktree, { recursive: true, force: true });

  git(SEER_REPO, "worktree", "add", "-b", branch, worktree, "origin/main");
  try {
    writeFileSync(join(worktree, GENERATED_PATH), content);
    git(worktree, "add", GENERATED_PATH);
    git(worktree, "commit", "-m", "deepfund: sync contest markets from ai-prediction-markets");
    git(worktree, "push", "-u", "origin", branch);
    const url = execFileSync(
      "gh",
      [
        "pr", "create",
        "--repo", SEER_GITHUB_REPO,
        "--base", "main",
        "--head", branch,
        "--title", "deepfund: sync contest markets",
        "--body",
        "Regenerated `web/src/lib/deepfundMarkets.generated.ts` from `DEEP_CONTESTS` in ai-prediction-markets (`npm run sync:seer`).\n\nBoards for new contests fill as the P&L refresh reaches each wallet after deploy.",
      ],
      { cwd: worktree, encoding: "utf8" },
    ).trim();
    console.log(url);
  } finally {
    git(SEER_REPO, "worktree", "remove", "--force", worktree);
  }
}

async function main() {
  if (args.has("--check")) return check();

  const content = renderFile();

  if (args.has("--write")) {
    writeFileSync(join(SEER_REPO, GENERATED_PATH), content);
    console.log(`wrote ${join(SEER_REPO, GENERATED_PATH)}`);
    return;
  }

  git(SEER_REPO, "fetch", "--quiet", "origin", "main");
  const upstreamApps = readOriginMain("web/src/lib/apps.ts") ?? "";
  if (!upstreamApps.includes("DEEPFUND_MARKETS")) {
    throw new Error(
      "Seer's origin/main does not read deepfundMarkets.generated.ts yet — merge the registry PR first (or use --write).",
    );
  }

  const current = readOriginMain(GENERATED_PATH) ?? "";
  const diff = diffStrings(current, content);
  if (!diff) {
    console.log("Seer's origin/main is already in sync with DEEP_CONTESTS.");
    return;
  }
  console.log(diff);
  if (args.has("--dry-run")) return;

  openPr(content);
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});
